  var myCavalry = 0;
  for (var ci = 0; ci < myUnits.length; ci++) {
    const u = myUnits[ci];
    if (!u) continue;
    if (u.type === "worker") myWorkers++;
    else if (u.type === "melee") myMelee++;
    else if (u.type === "ranged") myRanged++;
    else if (u.type === "cavalry") myCavalry++;
  }
  var myMilitary = myMelee + myRanged + myCavalry;

  var harvestableMines = 0;
  for (var mi = 0; mi < myResSites.length; mi++) {
