function isOnOwnedBase(u: Unit, myBases: Site[]): boolean {
  for (var i = 0; i < myBases.length; i++) {
    const b = myBases[i];
    if (b && b.x === u.x && b.y === u.y) return true;
  }
  return false;
}

function tryMoveOff(u: Unit): boolean {
